static const VnFont vnLon = {vnBitsLon, vnGlyphsLon, 230, 68};

inline uint32_t vnNext(const char *&p) {
  uint8_t c = (uint8_t)*p++;
  if (c < 0x80) return c;
  uint8_t n = (c >= 0xC2 && c <= 0xDF) ? 1 :
              (c >= 0xE0 && c <= 0xEF) ? 2 : (c >= 0xF0 && c <= 0xF4) ? 3 : 0;
  if (!n) return '?';
  uint32_t v = c & (0x7F >> n);
  for (uint8_t i = 0; i < n; ++i) {
    if (((uint8_t)*p & 0xC0) != 0x80) return '?';
    v = (v << 6) | ((uint8_t)*p++ & 0x3F);
  }
  return v;
}
inline const VnGlyph *vnFind(const VnFont &f, uint32_t cp) {
  int lo = 0, hi = f.count - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    uint16_t c = pgm_read_word(&f.glyphs[mid].code);
    if (c == cp) return &f.glyphs[mid];
    if (c < cp) lo = mid + 1; else hi = mid - 1;
  }
  return &f.glyphs['?' - 32];
}
inline int vnWidth(const char *s, const VnFont &f) {
  int w = 0;
  while (*s) w += pgm_read_byte(&vnFind(f, vnNext(s))->advance);
  return w;
}
inline void vnText(Adafruit_GFX &g, const char *s, int x, int y,
                   const VnFont &f, uint16_t color) {
  while (*s) {
    const VnGlyph *a = vnFind(f, vnNext(s));
    g.drawBitmap(x + (int8_t)pgm_read_byte(&a->x), y + (int8_t)pgm_read_byte(&a->y),
                 f.bits + pgm_read_word(&a->offset), pgm_read_byte(&a->w),
                 pgm_read_byte(&a->h), color);
    x += pgm_read_byte(&a->advance);
  }
}
inline void vnCenter(Adafruit_GFX &g, const char *s, int y,
                     const VnFont &f, uint16_t color) {
  vnText(g, s, (g.width() - vnWidth(s, f)) / 2, y, f, color);
}
